import json,sys,shutil
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from PIL import Image,ImageDraw,ImageFont
root=Path(sys.argv[1]);target=Path(sys.argv[2]);target.mkdir(parents=True,exist_ok=True);assets=target/'assets';assets.mkdir(exist_ok=True)
summary=json.loads((root/'summary.json').read_text());mapping=json.loads((root/'render-map.json').read_text());data={}
for row in mapping:
 case=row['case'];src=json.loads((root/'render'/f"frame-{row['index']:04d}.json").read_text());index=len(data.setdefault(case,[]));images={}
 for view in ['pressure','damage','mesh']:
  original=root/'native'/f"{view}-{row['index']:04d}.png";dest=assets/f'{case}-{view}-{index:03d}.png';shutil.copy2(original,dest);images[view]='assets/'+dest.name
 data[case].append({'time':row['time'],'elements':src['observation']['elements'],'images':images,'damage':src['observation']['maximum-damage'],'heat':src['observation']['heat-J']})
plt.style.use('dark_background');fig,axs=plt.subplots(2,2,figsize=(12,8),layout='constrained');colors={'coarse':'#a8b6ff','fine':'#ffb57e','adaptive':'#77e4bd'}
for mode,color in colors.items():
 for dt,style in [('0.25','-'),('0.5',':')]:
  case=mode+'-dt-'+dt;c=summary['curves'][case];label=mode+', dt '+dt+' s'
  axs[0,0].step(c['time'],c['elements'],where='post',color=color,linestyle=style,label=label)
  axs[0,1].plot(c['time'],np.array(c['energy-error'])*100,color=color,linestyle=style)
  axs[1,0].plot(c['time'],np.array(c['heat-J'])/1e6,color=color,linestyle=style)
  axs[1,1].plot(c['time'],c['maximum-damage'],color=color,linestyle=style)
for ax in axs.flat:ax.grid(alpha=.15);ax.set_xlabel('Simulated seconds')
axs[0,0].set_ylabel('Active material elements');axs[0,0].legend(fontsize=8,ncol=2)
axs[0,1].set_ylabel('Accounted energy error / %');axs[1,0].set_ylabel('Released heat / MJ');axs[1,1].set_ylabel('Peak damage softening')
fig.suptitle('Matched continuum impact: refinement, contact, dissipation and return to coarse resolution')
fig.savefig(assets/'measurements.png',dpi=150);plt.close(fig)
# A sampled native timelapse at dt=0.25, with all three physical policies visible.
font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',18);frames=[]
for index in range(22):
 image=Image.new('RGB',(1440,300),(8,16,25));draw=ImageDraw.Draw(image)
 for column,mode in enumerate(['coarse','fine','adaptive']):
  row=data[mode+'-dt-0.25'][index];p=target/row['images']['damage'];shot=Image.open(p).convert('RGB').crop((200,215,1000,550)).resize((480,230),Image.Resampling.LANCZOS)
  image.paste(shot,(column*480,55));draw.text((column*480+14,8),f"{mode.upper()} / {row['time']} s",font=font,fill='#d6eee8');draw.text((column*480+14,31),f"{row['elements']} active elements",font=font,fill='#85dcc0')
 frames.append(image)
frames[0].save(root/'continuum-impact.gif',save_all=True,append_images=frames[1:],duration=[250]*18+[450]*4,loop=0)
frames[8].save(root/'continuum-impact.png')
rows=''.join(f"<tr><td>{mode}</td><td>{summary['cases'][mode+'-dt-0.25']['maximum-absolute-energy-error-fraction']*100:.4f}%</td><td>{summary['cases'][mode+'-dt-0.25']['maximum-damage']:.4f}</td><td>{summary['cases'][mode+'-dt-0.25']['final-heat-J']/1e6:.2f} MJ</td></tr>" for mode in ['coarse','fine','adaptive'])
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Truth · Conservative continuum impact</title><style>:root{color-scheme:dark;font:17px/1.6 system-ui;background:#081019;color:#e0edf2}*{box-sizing:border-box}body{max-width:1380px;margin:auto;padding:28px 22px 70px}a{color:#8de3c9}nav{display:flex;gap:22px;flex-wrap:wrap;font-size:14px;margin-bottom:45px}.eyebrow{letter-spacing:.14em;font-size:12px;color:#85dabd}h1{font-size:clamp(38px,6vw,64px);line-height:1.08;letter-spacing:-.03em;max-width:1000px}h2{font-size:28px;margin-top:46px}p{max-width:950px;color:#b6cbd7}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}button,select{background:#18303a;color:#e2f7ee;border:1px solid #456a79;border-radius:7px;padding:10px 13px;cursor:pointer}.panels{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.panel{background:#11222d;border:1px solid #2e4d5b;border-radius:10px;overflow:hidden}.panel h3{font-size:16px;margin:12px 14px}.panel img{width:100%;display:block}.panel .caption{font-size:13px;color:#a2d7c6;padding:9px 14px}.status{color:#8ce5c1;margin:12px 0}input{width:100%;accent-color:#88e2c0}.note{padding:22px;border-left:3px solid #90b2ff;background:#122831;border-radius:7px}.plot{width:100%;margin:20px 0}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;border-bottom:1px solid #304c5a;padding:12px}.facts{display:flex;gap:34px;flex-wrap:wrap;margin:24px 0}.facts strong{display:block;font-size:27px;color:#89e0c1}.facts span{font-size:13px;color:#a8c0ce}footer{border-top:1px solid #304b59;margin-top:50px;padding-top:20px;font-size:13px;color:#88a3b1}@media(max-width:850px){.panels{grid-template-columns:1fr}.panel img{max-height:430px;object-fit:contain}body{padding:22px 14px}.facts{gap:22px}}</style></head><body><nav><a href="../">← Planetary Lab</a><a href="../rotation/">Earlier refinement failure</a><a href="../fine-cloud/">Granular cloud comparison</a></nav><div class="eyebrow">EXPERIMENT 06 · 24 OCTOBER 2026</div><h1>Refine the material.<br>Keep its accounted energy.</h1><p>A closed, deformable material patch receives the same finite-mass impact in three runs. The adaptive run refines before contact, retains detail through the stress pulse, then coarsens only after a projection passes conservation and error checks.</p><div class="facts"><div><strong>0 J</strong><span>measured refinement energy jump</span></div><div><strong>0.0053 J</strong><span>coarsening change, against about 289 MJ</span></div><div><strong>0.0847%</strong><span>maximum sampled fine/adaptive energy error at dt=0.25 s</span></div></div>
<div class="controls"><select id="dt" aria-label="Simulation timestep"><option value="0.25">dt 0.25 s</option><option value="0.5">dt 0.5 s</option></select><select id="view" aria-label="Physical view"><option value="damage">Damage softening</option><option value="pressure">Pressure</option><option value="mesh">Material mesh</option></select><button id="play">Play</button><button id="impact">Impact</button><button id="coarsen">After coarsening</button></div><p id="status" class="status" aria-live="polite"></p><div class="panels">PANELS</div><input id="seek" type="range" min="0" max="21" value="0" aria-label="Simulation frame"><p>All three panels show the same simulated time and timestep. Click a native frame to inspect it at full size. The camera follows the patch; the rebounding impactor remains in the recorded state after it leaves the view.</p><p>Orange object: cylindrical impactor in a plane-strain cross-section. Damage view: grey-blue to red denotes softening from 0 to 0.65. Pressure view: warm colors denote compression; the fixed color range saturates at ±20 kPa. Mesh view shows actual active material elements.</p>
<h2>The adaptive run earned its return to coarse resolution.</h2><p>With dt=0.25 s, it refines at 54.75 s with zero measured mass, momentum and energy residual. It rejects 19 later coarsening attempts, then accepts at 1220 s. The accounted energy change is −0.00531 J; no correction is added to heat. With dt=0.5 s, refinement occurs at 55 s and coarsening at 1290 s, after 26 rejected attempts.</p><p>Across the sampled states, the adaptive displacement field differs from the corresponding fully fine run by at most about 24 micrometres in mass-integrated RMS. This is agreement within this controlled numerical model, not a claim of physical rock accuracy.</p><h2>Conservation alone does not resolve the damage field.</h2><table><tr><th>Policy at dt=0.25 s</th><th>Maximum sampled energy error</th><th>Peak damage</th><th>Final released heat</th></tr>TABLE_ROWS</table><p>The coarse mesh produces substantially less local damage than the fine mesh. The adaptive run reproduces the fine result during impact. This is why a small energy residual cannot, by itself, decide which resolution is adequate.</p><img class="plot" src="assets/measurements.png" alt="Active elements, accounted energy error, released heat and damage in all six impact runs"><p>Halving the timestep reduces the fine/adaptive maximum sampled energy error from 0.1896% to 0.0847%. The retained plots sample the trajectories; handoff diagnostics are evaluated at the actual transitions.</p>
<h2>What changed from the earlier granular experiment</h2><p>The earlier eight-way sphere subdivision created new overlaps and a 4.30 GJ mechanical-energy discrepancy. This experiment uses an integrated elastic energy density, consistent finite-element inertia, and a fixed physical surface-contact quadrature. Affine interpolation can then subdivide a strained material element without introducing new stored energy.</p><p>The same pressure/shear law applies at both mesh sizes. Damage softening releases stored elastic energy into a tracked heat stock. A stated phenomenological relaxation closure damps non-rigid motion while preserving linear/angular momentum, and records the lost kinetic energy as heat.</p><div class="note"><strong>Scope of this experiment.</strong><p>This is a local plane-strain patch, extruded by 64 m for the native 3D view, using illustrative material parameters. It runs as a localized physical component under Truth’s existing ECS integrator and renderer. Self-gravity, external work, topological fracture, ejecta and a shock EOS are absent. Damage is softening, not a demonstrated crater or crack network. Finite silicate, H₂O and iron stocks are accounted; reaction chemistry and Primordia exchange remain future work.</p><p>Refinement covers the impacted patch as a unit. This demonstrates a compatible coarse/fine transfer mechanism; it does not yet establish planet-wide adaptive meshing. Coarsening uses an explicit numerical budget and retains fine history.</p></div><footer><p><a href="summary.json">Inspect measured traces and transitions</a> · <a href="../downloads/truth-continuum-impact-2026-10-24.zip">Download sources, raw states and launch recipe</a></p><p>Methods: <a href="https://docs.fenicsproject.org/dolfinx/main/cpp/demos/demo_hyperelasticity.html">FEniCS compressible neo-Hookean energy</a>; <a href="https://docs.mfem.org/4.8/ex10_8cpp_source.html">MFEM nonlinear elasticity and consistent inertia example</a>. These references motivate the numerical formulation; they do not validate these material parameters or experiment outcomes.</p><p>Focused verification and numerical limits are retained with the source bundle. Complete strict static analysis was unavailable.</p></footer><script>const data=DATA;let index=0,playing=false,timer;const $=id=>document.getElementById(id);function show(){const dt=$('dt').value,view=$('view').value;for(const mode of ['coarse','fine','adaptive']){const f=data[mode+'-dt-'+dt][index];$(mode+'-image').src=f.images[view];$(mode+'-link').href=f.images[view];$(mode+'-caption').textContent=`${f.elements} elements · heat ${(f.heat/1e6).toFixed(2)} MJ · peak damage ${f.damage.toFixed(3)}`}$('seek').value=index;$('status').textContent=`${data['adaptive-dt-'+dt][index].time} simulated seconds · matched dt ${dt} s`}function loop(){if(!playing)return;index=(index+1)%22;show();timer=setTimeout(loop,index<12?450:650)}$('dt').onchange=show;$('view').onchange=show;$('seek').oninput=e=>{index=+e.target.value;show()};$('impact').onclick=()=>{index=8;show()};$('coarsen').onclick=()=>{index=19;show()};$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause':'Play';clearTimeout(timer);if(playing)loop()};show();</script></body></html>'''
html=html.replace('PANELS',''.join(f'<article class="panel"><h3>{mode.title()}</h3><a id="{mode}-link"><img id="{mode}-image" alt="Native {mode} material impact capture"></a><div class="caption" id="{mode}-caption"></div></article>' for mode in ['coarse','fine','adaptive'])).replace('TABLE_ROWS',rows).replace('DATA',json.dumps(data,separators=(',',':')))
